// input: { success: true, links: [ { url: "..." } ] }
const items = $input.all();
const seen = new Set();
const out = [];

const ALLOWED_HOST = 'imtiaz.ae';

// blocked path prefixes (substring matched against pathname)
const BLOCK_PREFIXES = [
  '/press-blog','/newsletter','/assets-vault','/press','/gallery','/blog',
  '/news','/news-and-press','/events','/event/','/construction-history/',
  '/cookie-policy','/privacy-notice','/privacy-policy','/terms','/faq',
  '/careers','/pay-now','/3d-tour','/investor-relation','/contact-us'
];

// blocked exact paths (trailing-slash insensitive)
const BLOCK_EXACT = new Set(); // no exact-path blocks; keep about-us, properties, communities

for (const it of items) {
  const links = it.json.links || (it.json.url ? [it.json] : []);
  for (const link of links) {
    let raw = (link.url || '').trim();
    if (!raw) continue;

    // Drop XML/assets
    if (/\.(xml|pdf|jpg|jpeg|png|gif|svg|webp|ico|css|js|zip)$/i.test(raw)) continue;

    let u;
    try { u = new URL(raw); } catch { continue; }

    // host must be exactly imtiaz.ae (drop subdomains)
    if (u.hostname.toLowerCase() !== ALLOWED_HOST) continue;

    // only http/https
    if (!/^https?:$/.test(u.protocol)) continue;

    // strip query + fragment for canonical url (dedup ?utm_xxx)
    let path = u.pathname.replace(/\/+$/, '') || '/';
    const pathLower = path.toLowerCase();

    if (BLOCK_EXACT.has(pathLower)) continue;
    let blocked = false;
    for (const p of BLOCK_PREFIXES) {
      if (pathLower.startsWith(p)) { blocked = true; break; }
    }
    if (blocked) continue;

    const canonical = `https://${ALLOWED_HOST}${path}`;
    if (seen.has(canonical)) continue;
    seen.add(canonical);

    out.push({ json: { url: canonical } });
  }
}

return out;

const j = $json;
// HTTP errors from continueOnFail land here as { error: {...} }
if (j.error || !j.html || typeof j.html !== 'string') {
  return { url: j.url, project_id: j.project_id, text: '' };
}
const text = j.html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, '')
  .replace(/<!--([\s\S]*?)-->/g, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/\s+/g, ' ')
  .trim();
return { url: j.url, project_id: j.project_id, text };

const raw = $json.text || "";
const text = raw.replace(/\s+/g, " ").trim(); // clean whitespace
const chunkSize = 1000;
const overlap = 200;

const chunks = [];
let i = 0;

while (i < text.length) {
  const chunk = text.slice(i, i + chunkSize).trim();

  // Only save useful chunks
  if (chunk.length > 50) {
    chunks.push({
      content: chunk,
      url: $json.url,
      project_id: $json.project_id
    });
  }

  i += chunkSize - overlap;
}

return chunks;

const now = new Date();
const dateStr = now.toISOString().slice(0,10).replace(/-/g, "");
const random = Math.floor(1000 + Math.random() * 9000);
const ticket_id = `TKT-${dateStr}-${random}`;
return ticket_id;

